//! Bootstraps the generated hexagonal REST API.
//!
//! Wiring direction (hexagonal rules):
//!   HTTP handlers → enterprise buses → application services → domain ports
//!                                                      ↑
//!                                      PostgreSQL adapters (SQLx)
//!
//! Generated by `hex-gen` for schema `public` — edit the generator
//! templates rather than this file.

mod api;
mod application;
mod config;
mod domain;
mod enterprise;
mod error;
mod infrastructure;

use std::time::Duration;

use anyhow::Result;
use axum::Router;
use sqlx::postgres::PgPoolOptions;
use utoipa::OpenApi;
use utoipa_swagger_ui::SwaggerUi;

use crate::api::openapi::ApiDoc;
use crate::api::routes;
use crate::api::state::AppState;
use crate::config::Config;
use crate::enterprise::bus::{CommandBus, QueryBus};
use crate::application::orders_messaging::{OrdersHandlers, CreateOrdersCommand, DeleteOrdersCommand, GetOrdersQuery, ListOrdersQuery, UpdateOrdersCommand, ListOrdersByStatusQuery, SetOrdersStatusCommand, RestoreOrdersCommand, SoftDeleteOrdersCommand, ListOrdersByUserQuery, ListOrdersCreatedAfterQuery, ListOrdersUpdatedAfterQuery};
use crate::application::orders_service::OrdersServiceImpl;
use crate::domain::orders::service::OrdersService;
use crate::infrastructure::orders_repository::PostgresOrdersRepository;
use crate::application::product_categories_messaging::{ProductCategoriesHandlers, CreateProductCategoriesCommand, DeleteProductCategoriesCommand, GetProductCategoriesQuery, ListProductCategoriesQuery, UpdateProductCategoriesCommand, ListProductCategoriesByStatusQuery, SetProductCategoriesStatusCommand, ListProductCategoriesCreatedAfterQuery};
use crate::application::product_categories_service::ProductCategoriesServiceImpl;
use crate::domain::product_categories::service::ProductCategoriesService;
use crate::infrastructure::product_categories_repository::PostgresProductCategoriesRepository;
use crate::application::users_messaging::{UsersHandlers, CreateUsersCommand, DeleteUsersCommand, GetUsersQuery, ListUsersQuery, UpdateUsersCommand, ListUsersByStatusQuery, SetUsersStatusCommand, ListUsersCreatedAfterQuery, ListUsersUpdatedAfterQuery};
use crate::application::users_service::UsersServiceImpl;
use crate::domain::users::service::UsersService;
use crate::infrastructure::users_repository::PostgresUsersRepository;

#[tokio::main]
async fn main() -> Result<()> {
    dotenvy::dotenv().ok();
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let config = Config::from_env()?;
    let pool = PgPoolOptions::new()
        .max_connections(config.db_max_connections)
        .acquire_timeout(Duration::from_secs(15))
        .connect(&config.database_url)
        .await?;
    tracing::info!("connected to PostgreSQL (schema: public)");

    // ── enterprise buses ────────────────────────────────────────────────────
    let mut cmd_bus = CommandBus::new();
    let mut qry_bus = QueryBus::new();

    // ── orders context ────────────────────────────────────────────────────
    let orders_repo = std::sync::Arc::new(PostgresOrdersRepository::new(pool.clone()));
    let orders_service: std::sync::Arc<dyn OrdersService> = std::sync::Arc::new(OrdersServiceImpl::new(orders_repo));
    let orders_handlers = OrdersHandlers::new(orders_service);

    cmd_bus.register::<CreateOrdersCommand, _>(orders_handlers.clone());
    cmd_bus.register::<UpdateOrdersCommand, _>(orders_handlers.clone());
    cmd_bus.register::<DeleteOrdersCommand, _>(orders_handlers.clone());
    cmd_bus.register::<SetOrdersStatusCommand, _>(orders_handlers.clone());
    cmd_bus.register::<SoftDeleteOrdersCommand, _>(orders_handlers.clone());
    cmd_bus.register::<RestoreOrdersCommand, _>(orders_handlers.clone());

    qry_bus.register::<GetOrdersQuery, _>(orders_handlers.clone());
    qry_bus.register::<ListOrdersQuery, _>(orders_handlers.clone());
    qry_bus.register::<ListOrdersByStatusQuery, _>(orders_handlers.clone());
    qry_bus.register::<ListOrdersByUserQuery, _>(orders_handlers.clone());
    qry_bus.register::<ListOrdersCreatedAfterQuery, _>(orders_handlers.clone());
    qry_bus.register::<ListOrdersUpdatedAfterQuery, _>(orders_handlers.clone());

    // ── product_categories context ────────────────────────────────────────────────────
    let product_categories_repo = std::sync::Arc::new(PostgresProductCategoriesRepository::new(pool.clone()));
    let product_categories_service: std::sync::Arc<dyn ProductCategoriesService> = std::sync::Arc::new(ProductCategoriesServiceImpl::new(product_categories_repo));
    let product_categories_handlers = ProductCategoriesHandlers::new(product_categories_service);

    cmd_bus.register::<CreateProductCategoriesCommand, _>(product_categories_handlers.clone());
    cmd_bus.register::<UpdateProductCategoriesCommand, _>(product_categories_handlers.clone());
    cmd_bus.register::<DeleteProductCategoriesCommand, _>(product_categories_handlers.clone());
    cmd_bus.register::<SetProductCategoriesStatusCommand, _>(product_categories_handlers.clone());

    qry_bus.register::<GetProductCategoriesQuery, _>(product_categories_handlers.clone());
    qry_bus.register::<ListProductCategoriesQuery, _>(product_categories_handlers.clone());
    qry_bus.register::<ListProductCategoriesByStatusQuery, _>(product_categories_handlers.clone());
    qry_bus.register::<ListProductCategoriesCreatedAfterQuery, _>(product_categories_handlers.clone());

    // ── users context ────────────────────────────────────────────────────
    let users_repo = std::sync::Arc::new(PostgresUsersRepository::new(pool.clone()));
    let users_service: std::sync::Arc<dyn UsersService> = std::sync::Arc::new(UsersServiceImpl::new(users_repo));
    let users_handlers = UsersHandlers::new(users_service);

    cmd_bus.register::<CreateUsersCommand, _>(users_handlers.clone());
    cmd_bus.register::<UpdateUsersCommand, _>(users_handlers.clone());
    cmd_bus.register::<DeleteUsersCommand, _>(users_handlers.clone());
    cmd_bus.register::<SetUsersStatusCommand, _>(users_handlers.clone());

    qry_bus.register::<GetUsersQuery, _>(users_handlers.clone());
    qry_bus.register::<ListUsersQuery, _>(users_handlers.clone());
    qry_bus.register::<ListUsersByStatusQuery, _>(users_handlers.clone());
    qry_bus.register::<ListUsersCreatedAfterQuery, _>(users_handlers.clone());
    qry_bus.register::<ListUsersUpdatedAfterQuery, _>(users_handlers.clone());

    let state = AppState {
        cmd: std::sync::Arc::new(cmd_bus),
        qry: std::sync::Arc::new(qry_bus),
    };

    // ── HTTP surface ─────────────────────────────────────────────────────────
    let api_router = routes::router().with_state(state);
    let app = Router::new()
        .merge(
            SwaggerUi::new("/swagger-ui")
                .url("/api-docs/openapi.json", ApiDoc::openapi()),
        )
        .nest("/api/v1", api_router);

    let listener = tokio::net::TcpListener::bind(&config.bind_address).await?;
    tracing::info!("HTTP server listening on http://{}", config.bind_address);
    tracing::info!("Swagger UI at http://{}/swagger-ui", config.bind_address);
    axum::serve(listener, app).await?;
    Ok(())
}
